from threetears.evals import Eval

from rates import quote


def price(case):
    """Quote one consignment as the desk quotes it."""
    return {"pence": quote(case["weight_kg"], case["zone"], signed=case["signed"]).pence}


def matches_invoice(case, out):
    """Our quote comes to what the courier charged for the consignment."""
    return out["pence"] == case["charged_pence"]


invoice = Eval("data/courier_invoice.jsonl", runner=price, grader=[matches_invoice], k=1)
